"""Code-free native tokenizer loading for reviewed Kimi K3/K3.1 sources.

Kimi K3 and K3.1 ship a tiktoken vocabulary (``tiktoken.model``) behind a
remote-code ``TikTokenTokenizer`` and no ``tokenizer.json``. This module
converts the pinned data files into an id-identical fast tokenizer entirely
from reviewed installed code, so host loading never imports
checkpoint-staged Python and ``auto_map`` metadata stays inert.

Only data files are read. ``tokenization_kimi.py`` is hash-checked as
provenance evidence (the token pattern and reserved-token count below are
copied from it) but never imported. The two models share one byte-identical
vocabulary; their XTML chat encoders are distinct reviewed contracts,
vendored separately by the cookbook renderers and never aliased here.

The cookbook wrapper ``training.utils.kimi_native_tokenizer`` delegates to
this module when ``KIMI_NATIVE_TOKENIZER_CAPABILITY`` matches and otherwise
falls back to its generated snapshot, so older installed SDKs keep the same
behavior.
"""

from __future__ import annotations

import json
import hashlib
from typing import Any
from pathlib import Path
from functools import cached_property
from importlib import import_module

# Capability marker for cookbook delegation, same contract as
# TOKENIZER_IDENTITY_POLICY_CAPABILITY: the wrapper defers to this module
# only when the constant matches exactly, so an intermediate SDK falls back
# to the cookbook's pinned snapshot instead of inheriting older behavior.
KIMI_NATIVE_TOKENIZER_CAPABILITY = "kimi-k3-k31-native-tokenizer/chat-and-saved-bundles-v3"

KIMI_K3_PROFILE = "kimi_k3"
KIMI_K31_PROFILE = "kimi_k31"

KIMI_K3_REPOSITORY = "moonshotai/Kimi-K3"
KIMI_K3_REVISION = "301be1b88c89c0d3a763da6301352cb8fe399e90"
KIMI_K31_REPOSITORY = "moonshotai/Kimi-K3.1-Pro"
KIMI_K31_REVISION = "d9e99b0792a5e93b78ea9bea62a68167e36ddd9e"

# Pinned source files per profile. ``tiktoken.model`` is byte-identical
# across both; ``tokenizer_config.json`` differs only in formatting, and
# ``tokenization_kimi.py`` only in formatting (the token pattern is the
# same), but each profile pins its own reviewed bytes.
KIMI_K3_SOURCE_SHA256 = {
    "tiktoken.model": "b6c497a7469b33ced9c38afb1ad6e47f03f5e5dc05f15930799210ec050c5103",
    "tokenizer_config.json": "5d0803c94db9cd78763499e0956c95fd5a225c14a727e5a6cf5db3f96f010a6e",
    "tokenization_kimi.py": "f28ea66e2d862a2a5814970b2ce40c2f7d8296ff09aed90a7e7def689b906944",
}
KIMI_K31_SOURCE_SHA256 = {
    "tiktoken.model": "b6c497a7469b33ced9c38afb1ad6e47f03f5e5dc05f15930799210ec050c5103",
    "tokenizer_config.json": "9fc322181b8ec44236e148916aea4b6c2467b66ded7bfaff0efe623ad750b852",
    "tokenization_kimi.py": "204ee39fbf13a6d6608b0d3ca1b4b04a14ac5f0a062a7fdee02e61f5d936f9c6",
}
KIMI_SOURCE_SHA256_BY_PROFILE = {
    KIMI_K3_PROFILE: KIMI_K3_SOURCE_SHA256,
    KIMI_K31_PROFILE: KIMI_K31_SOURCE_SHA256,
}
KIMI_REPOSITORY_BY_PROFILE = {
    KIMI_K3_PROFILE: KIMI_K3_REPOSITORY,
    KIMI_K31_PROFILE: KIMI_K31_REPOSITORY,
}
KIMI_REVISION_BY_PROFILE = {
    KIMI_K3_PROFILE: KIMI_K3_REVISION,
    KIMI_K31_PROFILE: KIMI_K31_REVISION,
}
_PROFILE_BY_REPOSITORY = {repository: profile for profile, repository in KIMI_REPOSITORY_BY_PROFILE.items()}
_ENCODER_MODULES = {
    KIMI_K3_PROFILE: "training.renderer._vendored.kimi_k3.encoding_k3",
    KIMI_K31_PROFILE: "training.renderer.tito._vendored.kimi_k31.encoding_k3",
}
_PROFILE_KEY = "kimi_native_profile"

# ``TikTokenTokenizer.pat_str`` and ``num_reserved_special_tokens`` from the
# pinned ``tokenization_kimi.py`` (identical in both profiles).
KIMI_K3_K31_PAT_STR = "|".join(
    [
        r"""[\p{Han}]+""",
        r"""[^\r\n\p{L}\p{N}]?[\p{Lu}\p{Lt}\p{Lm}\p{Lo}\p{M}&&[^\p{Han}]]*[\p{Ll}\p{Lm}\p{Lo}\p{M}&&[^\p{Han}]]+(?i:'s|'t|'re|'ve|'m|'ll|'d)?""",
        r"""[^\r\n\p{L}\p{N}]?[\p{Lu}\p{Lt}\p{Lm}\p{Lo}\p{M}&&[^\p{Han}]]+[\p{Ll}\p{Lm}\p{Lo}\p{M}&&[^\p{Han}]]*(?i:'s|'t|'re|'ve|'m|'ll|'d)?""",
        r"""\p{N}{1,3}""",
        r""" ?[^\s\p{L}\p{N}]+[\r\n]*""",
        r"""\s*[\r\n]+""",
        r"""\s+(?!\S)""",
        r"""\s+""",
    ]
)
KIMI_NUM_RESERVED_SPECIAL_TOKENS = 256
KIMI_BASE_VOCAB_SIZE = 163_584

_BOS, _EOS, _UNK, _PAD = "[BOS]", "[EOS]", "[UNK]", "[PAD]"


class _NativeChatTemplate:
    """The reviewed tokenizer's chat API, without importing checkpoint Python.

    Keep the standard fast tokenizer class/backend serializable. The callable
    is installed on load; only its profile (data, not code) is saved in config.
    The two private backends avoid mutating a tokenizer shared by other threads.
    """

    def __init__(self, tokenizer: Any, profile: str) -> None:
        self.tokenizer = tokenizer
        self.profile = profile

    def __getstate__(self) -> dict[str, Any]:
        # tokenizers' pickle does not preserve encode_special_tokens. Rebuild
        # our private backends so literal control-looking text stays ordinary.
        state = self.__dict__.copy()
        state.pop("backends", None)
        return state

    @property
    def encoder(self) -> Any:
        # Do not store a module on the tokenizer: ordinary tokenizer pickling
        # must continue to work. import_module already caches installed code.
        return import_module(_ENCODER_MODULES[self.profile])

    @cached_property
    def backends(self) -> tuple[Any, Any]:
        # lazy: tokenize=False renders without copying a large vocabulary.
        from tokenizers import Tokenizer

        serialized = self.tokenizer.backend_tokenizer.to_str()
        special, text = Tokenizer.from_str(serialized), Tokenizer.from_str(serialized)
        for backend in (special, text):
            backend.no_padding()
            backend.no_truncation()
        special.encode_special_tokens = False
        text.encode_special_tokens = True
        return special, text

    def encode_segments(self, segments: list[Any]) -> list[int]:
        tokens: list[int] = []
        for segment in segments:
            backend = self.backends[0 if segment.allow_special else 1]
            # Same chunk boundaries as the release TikTokenTokenizer.
            text = segment.text
            for offset in range(0, len(text), 400_000):
                chunk = text[offset : offset + 400_000]
                start, length = 0, 0
                is_space = chunk[0].isspace() if chunk else False
                for index, char in enumerate(chunk):
                    current = char.isspace()
                    length = length + 1 if current == is_space else 1
                    is_space = current
                    if length > 25_000:
                        tokens.extend(backend.encode(chunk[start:index], add_special_tokens=False).ids)
                        start, length = index, 1
                if chunk[start:]:
                    tokens.extend(backend.encode(chunk[start:], add_special_tokens=False).ids)
        return tokens

    def __call__(
        self,
        conversation: Any,
        tools: list[dict[str, Any]] | None = None,
        tokenize: bool = False,
        add_generation_prompt: bool = True,
        thinking: bool = True,
        padding: Any = False,
        truncation: bool = False,
        max_length: int | None = None,
        return_tensors: Any = None,
        return_dict: bool = False,
        **kwargs: Any,
    ) -> Any:
        is_batched = self.encoder.is_batched_conversation(conversation)
        conversations = conversation if is_batched else [conversation]
        image_prompts = kwargs.pop("image_prompts", None)
        if is_batched and image_prompts is not None:
            raise ValueError("image_prompts is only supported for one chat.")
        kwargs.setdefault("thinking_effort", "max")
        batches = [
            self.encoder.build_chat_segments(
                messages,
                tools=tools,
                add_generation_prompt=add_generation_prompt,
                thinking=thinking,
                image_prompts=image_prompts,
                **kwargs,
            )
            for messages in conversations
        ]
        if not tokenize:
            rendered = ["".join(segment.text for segment in segments) for segments in batches]
            return rendered if is_batched else rendered[0]
        encoded = [self.encode_segments(segments) for segments in batches]
        if truncation and max_length is not None:
            encoded = [ids[:max_length] for ids in encoded]
        if not (is_batched or padding or return_tensors is not None or return_dict):
            return encoded[0]
        batch = self.tokenizer.pad(
            [{"input_ids": ids, "attention_mask": [1] * len(ids)} for ids in encoded],
            padding=padding,
            max_length=max_length if padding else None,
            return_attention_mask=True,
            return_tensors=return_tensors,
        )
        if return_dict:
            return batch
        if is_batched or return_tensors is not None:
            return batch["input_ids"]
        return batch["input_ids"][0]


def _attach_chat_template(tokenizer: Any, profile: str | None) -> Any:
    if profile is not None:
        if not isinstance(profile, str) or profile not in _ENCODER_MODULES:
            raise ValueError(f"unknown Kimi tokenizer profile {profile!r}")
        tokenizer.init_kwargs[_PROFILE_KEY] = profile
        tokenizer.apply_chat_template = _NativeChatTemplate(tokenizer, profile)
    return tokenizer


def _sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def verify_source_dir(source_dir: str | Path, *, profile: str | None = None) -> str:
    """Fail closed unless every pinned source file is present and unchanged.

    With ``profile`` unset, either reviewed profile is accepted; the matched
    profile name is returned. The tiktoken vocabulary digest is shared, so a
    directory mixing one profile's vocabulary with the other's
    ``tokenizer_config.json``/``tokenization_kimi.py`` is rejected.
    """
    root = Path(source_dir)
    profiles = [profile] if profile is not None else sorted(KIMI_SOURCE_SHA256_BY_PROFILE)
    mismatched: dict[str, list[str]] = {}
    for candidate in profiles:
        pins = KIMI_SOURCE_SHA256_BY_PROFILE.get(candidate)
        if pins is None:
            raise ValueError(f"unknown Kimi tokenizer profile {candidate!r}")
        problems = []
        for filename, expected in sorted(pins.items()):
            path = root / filename
            if not path.is_file():
                problems.append(f"{filename}: missing")
            elif _sha256(path) != expected:
                problems.append(f"{filename}: sha256 {_sha256(path)} != {expected}")
        if not problems:
            return candidate
        mismatched[candidate] = problems
    details = "; ".join(f"{name}: " + ", ".join(problems) for name, problems in mismatched.items())
    raise ValueError(f"Kimi K3/K3.1 tokenizer sources do not match the reviewed pins: {details}")


def special_tokens(source_dir: str | Path) -> list[tuple[str, int]]:
    """Every special token in id order, named exactly as ``TikTokenTokenizer`` names them."""
    root = Path(source_dir)
    config = json.loads((root / "tokenizer_config.json").read_text(encoding="utf-8"))
    named = {int(token_id): entry["content"] for token_id, entry in config.get("added_tokens_decoder", {}).items()}
    first = KIMI_BASE_VOCAB_SIZE
    return [
        (named.get(token_id, f"<|reserved_token_{token_id}|>"), token_id)
        for token_id in range(first, first + KIMI_NUM_RESERVED_SPECIAL_TOKENS)
    ]


def build_fast_tokenizer(source_dir: str | Path, *, profile: str | None = None) -> Any:
    """Convert the pinned tiktoken vocabulary into an id-identical fast tokenizer.

    ``TikTokenConverter`` appends special tokens after the base vocabulary in
    the order given, so every one of the 256 reserved ids is added explicitly in
    id order; passing only the named tokens would shift their ids.
    """
    # lazy: conversion needs the optional tokenizers/transformers stack.
    from tokenizers import AddedToken
    from transformers import PreTrainedTokenizerFast as TokenizersBackend
    from transformers.convert_slow_tokenizer import TikTokenConverter

    root = Path(source_dir)
    profile = verify_source_dir(root, profile=profile)
    backend = TikTokenConverter(
        vocab_file=str(root / "tiktoken.model"),
        pattern=KIMI_K3_K31_PAT_STR,
        additional_special_tokens=[],
    ).converted()
    if backend.get_vocab_size() != KIMI_BASE_VOCAB_SIZE:
        raise ValueError(
            f"Kimi K3/K3.1 base vocabulary has {backend.get_vocab_size()} tokens, expected {KIMI_BASE_VOCAB_SIZE}"
        )
    ordered = special_tokens(root)
    backend.add_special_tokens([AddedToken(name, special=True, normalized=False) for name, _ in ordered])
    for name, token_id in ordered:
        if backend.token_to_id(name) != token_id:
            raise ValueError(f"special token {name!r} landed at {backend.token_to_id(name)}, expected {token_id}")
    tokenizer = TokenizersBackend(
        tokenizer_object=backend,
        bos_token=_BOS,
        eos_token=_EOS,
        unk_token=_UNK,
        pad_token=_PAD,
        clean_up_tokenization_spaces=False,
    )
    # Renderer pickling reconstructs the tokenizer from ``name_or_path``; the
    # verified source dir reloads through the same code-free path.
    tokenizer.name_or_path = str(root)
    return _attach_chat_template(tokenizer, profile)


def _download_source(
    tokenizer_model: str,
    *,
    revision: str | None,
    local_files_only: bool,
) -> Path:
    """Fetch only tokenizer data/provenance files, never model weights."""
    # lazy: Hugging Face access is needed only for hub sources.
    from huggingface_hub import snapshot_download

    return Path(
        snapshot_download(
            repo_id=tokenizer_model,
            revision=revision,
            allow_patterns=["tiktoken.model", "tokenizer.json", "tokenizer_config.json", "tokenization_kimi.py"],
            local_files_only=local_files_only,
        )
    )


def load_native_tokenizer(
    tokenizer_model: str,
    *,
    revision: str | None = None,
    local_files_only: bool = False,
    profile: str | None = None,
) -> Any:
    """Load raw reviewed Kimi data or an installed-code tokenizer override.

    This is the code-free replacement for
    ``AutoTokenizer.from_pretrained(..., trust_remote_code=True)`` on
    recognized Kimi sources. It reads only data files, verifies every pinned
    byte digest, and builds the tokenizer from reviewed installed code.
    Raw tiktoken inputs always retain all pin checks, even if tokenizer.json
    is also present. Saved fast bundles are already converted: load their JSON
    directly with the installed backend, ignoring auto_map. Selected Kimi
    context constrains an unrelated override to installed code, but does not
    force it through raw conversion or assign it a Kimi chat profile.

    Official repositories default to their pinned reviewed revisions so the
    byte digests below certify immutable data, not a mutable ``main``.
    """
    source = Path(tokenizer_model)
    if not source.is_dir():
        if profile is None:
            profile = _PROFILE_BY_REPOSITORY.get(tokenizer_model)
        if revision is None and profile is not None:
            revision = KIMI_REVISION_BY_PROFILE[profile]
        source = _download_source(tokenizer_model, revision=revision, local_files_only=local_files_only)
        if not any((source / name).is_file() for name in ("tiktoken.model", "tokenizer.json")):
            # A built-in slow override may need vocab files outside our raw
            # conversion allowlist. Keep its Hub identity/revision, but never
            # allow checkpoint code to resolve its class.
            # lazy: only built-in slow overrides need AutoTokenizer.
            from transformers import AutoTokenizer

            return AutoTokenizer.from_pretrained(
                tokenizer_model, revision=revision, local_files_only=local_files_only, trust_remote_code=False
            )
        tokenizer = load_native_tokenizer(str(source), profile=profile)
        # Restore through the repository identity (re-pinned and re-verified)
        # rather than a local cache path that may not exist on another host.
        tokenizer.name_or_path = tokenizer_model
        return tokenizer
    if (source / "tiktoken.model").is_file():
        return build_fast_tokenizer(source, profile=profile)
    if (source / "tokenizer.json").is_file():
        # lazy: direct backend loading cannot resolve checkpoint auto_map.
        from transformers import PreTrainedTokenizerFast as TokenizersBackend

        config_path = source / "tokenizer_config.json"
        config = json.loads(config_path.read_text(encoding="utf-8")) if config_path.is_file() else {}
        tokenizer = TokenizersBackend.from_pretrained(
            str(source), tokenizer_file=str(source / "tokenizer.json"), trust_remote_code=False
        )
        # A saved profile is explicit data. An unrelated override gets no
        # inferred Kimi chat encoder, even when the base model is Kimi.
        return _attach_chat_template(tokenizer, config.get(_PROFILE_KEY))
    # lazy: built-in slow overrides remain valid, with checkpoint Python denied.
    from transformers import AutoTokenizer

    return AutoTokenizer.from_pretrained(str(source), trust_remote_code=False, local_files_only=local_files_only)


